object Solution {
  def numPoints(darts: Array[Array[Int]], r: Int): Int = {
    import scala.math._

    val n = darts.length
    if (n == 1) return 1

    // Calculate distance between two points
    def dist(a: Array[Int], b: Array[Int]): Double = {
      val dx = a(0) - b(0)
      val dy = a(1) - b(1)
      sqrt(dx * dx + dy * dy)
    }

    // Given two points and radius r, find the centers of the circles with radius r that pass through both points
    def getCenters(p1: Array[Int], p2: Array[Int], r: Double): Seq[(Double, Double)] = {
      val (x1, y1) = (p1(0).toDouble, p1(1).toDouble)
      val (x2, y2) = (p2(0).toDouble, p2(1).toDouble)
      val d = dist(p1, p2)
      if (d > 2 * r) return Seq.empty

      val midX = (x1 + x2) / 2.0
      val midY = (y1 + y2) / 2.0

      val base = sqrt(r * r - (d / 2) * (d / 2))

      // vector from p1 to p2
      val vx = (x2 - x1) / d
      val vy = (y2 - y1) / d

      // perpendicular vectors
      val cx1 = midX + base * (-vy)
      val cy1 = midY + base * vx
      val cx2 = midX - base * (-vy)
      val cy2 = midY - base * vx

      Seq((cx1, cy1), (cx2, cy2))
    }

    var maxCount = 1

    for (i <- 0 until n) {
      for (j <- i + 1 until n) {
        val centers = getCenters(darts(i), darts(j), r.toDouble)
        for ((cx, cy) <- centers) {
          var count = 0
          for (k <- 0 until n) {
            val dx = darts(k)(0) - cx
            val dy = darts(k)(1) - cy
            if (dx * dx + dy * dy <= r.toDouble * r.toDouble + 1e-9) count += 1
          }
          maxCount = max(maxCount, count)
        }
      }
    }

    maxCount
  }
}

